<?php
namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable;
class User extends Authenticatable {use HasFactory,Notifiable; protected $fillable=['name','email','username','password','role','class_id','is_active','last_login_at'];protected $hidden=['password','remember_token'];protected $casts=['password'=>'hashed','is_active'=>'boolean','last_login_at'=>'datetime'];public function schoolClass(){return $this->belongsTo(SchoolClass::class,'class_id');}public function recordedAttendances(){return $this->hasMany(Attendance::class,'recorded_by');}public function isAdmin():bool{return $this->role==='admin';}public function isWali():bool{return $this->role==='wali_kelas';}}
